import json

qs = []
q_id = 1

def add(ch, diff, q, opts, correct, expl):
    global q_id
    qs.append({
        "id": f"P{q_id:03d}",
        "subject": "Physics",
        "chapter": ch,
        "difficulty": diff,
        "question": q,
        "options": opts,
        "correct": correct,
        "explanation": expl
    })
    q_id += 1

# Units (P001-P010)
add("Units, Dimensions, & Vectors", "M", "Which of the following physical quantities has the same dimensional formula as Planck's constant (h)?", ["Work", "Angular Momentum", "Linear Momentum", "Energy density"], 1, "Planck's constant h has dimensions [M L^2 T^-1]. Angular momentum L = r x p also has dimensions [M L^2 T^-1].")
add("Units, Dimensions, & Vectors", "H", "The velocity v of a particle depends on time t according to v = a t + b / (t + c). The dimensions of a, b, and c are respectively:", ["[L T^-2], [L], [T]", "[L T^-1], [L T], [T]", "[L T^-2], [L T], [T]", "[L], [L T^-1], [T^-1]"], 0, "By dimensional homogeneity: [c] = [t] = [T]. [a t] = [v] => [a] = [L T^-2]. [b / (t+c)] = [v] => [b] / [T] = [L T^-1] => [b] = [L].")
add("Units, Dimensions, & Vectors", "M", "Two vectors A and B have equal magnitudes of 10 units each. If their resultant has a magnitude of 10√3 units, the angle between A and B is:", ["30°", "45°", "60°", "90°"], 2, "R^2 = A^2 + B^2 + 2AB cos θ => 300 = 100 + 100 + 200 cos θ => cos θ = 0.5 => θ = 60°.")
add("Units, Dimensions, & Vectors", "H", "If force (F), velocity (V), and time (T) are taken as fundamental physical quantities, the dimensional formula for mass is:", ["[F V^-1 T]", "[F V T^-1]", "[F V^-2 T]", "[F V T]"], 0, "F = m a = m (V / T) => m = [F V^-1 T].")
add("Units, Dimensions, & Vectors", "H", "The angle made by the vector A = 2i + 3j with the Y-axis is:", ["sin^-1(2/3)", "tan^-1(2/3)", "tan^-1(3/2)", "cos^-1(2/3)"], 1, "tan α = A_x / A_y = 2/3 => α = tan^-1(2/3).")
add("Units, Dimensions, & Vectors", "M", "Which of the following pairs of physical quantities has DIFFERENT dimensions?", ["Impulse and Momentum", "Work and Torque", "Stress and Young's Modulus", "Electric Field and Electric Potential"], 3, "Electric Field [E] = [M L T^-3 A^-1], Electric Potential [V] = [M L^2 T^-3 A^-1]. They differ by length dimension [L].")
add("Units, Dimensions, & Vectors", "H", "The magnitude of the cross product of two vectors is √3 times their dot product. The angle between the two vectors is:", ["30°", "45°", "60°", "90°"], 2, "|A x B| = √3 (A . B) => AB sin θ = √3 AB cos θ => tan θ = √3 => θ = 60°.")
add("Units, Dimensions, & Vectors", "H", "If the percentage errors in measuring mass, length, and time are 1%, 2%, and 3% respectively, the maximum percentage error in calculating kinetic energy (E = 0.5 m L^2 T^-2) is:", ["5%", "7%", "9%", "11%"], 3, "% error = 1% + 2(2%) + 2(3%) = 1 + 4 + 6 = 11%.")
add("Units, Dimensions, & Vectors", "M", "Unit vector along the direction of vector A = 3i + 4j - 5k is:", ["(3i + 4j - 5k) / 5", "(3i + 4j - 5k) / 50", "(3i + 4j - 5k) / 5√2", "(3i + 4j - 5k) / 10"], 2, "|A| = √(9 + 16 + 25) = √50 = 5√2. Unit vector = A / |A| = (3i + 4j - 5k) / 5√2.")
add("Units, Dimensions, & Vectors", "H", "Dimensions of gravitational constant G are [M^a L^b T^c]. The values of a, b, and c are:", ["a = -1, b = 3, c = -2", "a = 1, b = -3, c = 2", "a = -1, b = 2, c = -2", "a = 1, b = 3, c = -2"], 0, "G = F r^2 / m^2 = [M L T^-2][L^2]/[M^2] = [M^-1 L^3 T^-2]. Thus a = -1, b = 3, c = -2.")

# Kinematics (P011-P020)
add("Kinematics", "M", "A car accelerates from rest at 2 m/s² for 10 seconds. The total distance covered is:", ["50 m", "100 m", "150 m", "200 m"], 1, "s = ut + 0.5 a t^2 = 0 + 0.5(2)(10^2) = 100 m.")
add("Kinematics", "H", "A ball is thrown vertically upwards with velocity 20 m/s from the top of a 25 m tall tower. The time taken to hit the ground is (g = 10 m/s²):", ["3 s", "4 s", "5 s", "6 s"], 2, "-25 = 20t - 5t^2 => 5t^2 - 20t - 25 = 0 => t^2 - 4t - 5 = 0 => (t-5)(t+1) = 0 => t = 5 s.")
add("Kinematics", "M", "A body covers 18 m in the 5th second of its motion starting from rest under uniform acceleration. The acceleration of the body is:", ["2 m/s²", "4 m/s²", "3 m/s²", "5 m/s²"], 1, "s_n = u + 0.5 a(2n-1) => 18 = 0 + 0.5 a(2*5-1) = 4.5 a => a = 18 / 4.5 = 4 m/s².")
add("Kinematics", "H", "A train 150 m long passes a 850 m long bridge at a uniform speed of 72 km/h. Time taken by the train to cross the bridge is:", ["30 s", "40 s", "50 s", "60 s"], 2, "Total distance = 150 + 850 = 1000 m. Speed = 72 * 5/18 = 20 m/s. Time = 1000 / 20 = 50 s.")
add("Kinematics", "H", "A body covers 12 m in 2nd second and 20 m in 4th second under uniform acceleration. Its initial velocity u and acceleration a are:", ["u = 2 m/s, a = 4 m/s²", "u = 4 m/s, a = 4 m/s²", "u = 6 m/s, a = 4 m/s²", "u = 8 m/s, a = 4 m/s²"], 2, "s_2 = u + 1.5a = 12, s_4 = u + 3.5a = 20. Subtracting gives 2a = 8 => a = 4 m/s², u = 12 - 6 = 6 m/s.")
add("Kinematics", "M", "The ratio of distance travelled in 1st, 2nd, and 3rd seconds by a body falling freely from rest is:", ["1 : 2 : 3", "1 : 3 : 5", "1 : 4 : 9", "1 : 1 : 1"], 1, "Galileo's law of odd numbers: s_1st : s_2nd : s_3rd = 1 : 3 : 5.")
add("Kinematics", "H", "Two cars A and B move in the same direction with speeds 20 m/s and 10 m/s. If car A is 100 m behind B and decelerates at 2 m/s², the minimum distance between them before A stops is:", ["25 m", "50 m", "75 m", "100 m"], 2, "v_rel = 20 - 10 = 10 m/s, a_rel = -2 m/s². Relative stopping distance s = 10^2 / (2*2) = 25 m. Min distance = 100 - 25 = 75 m.")
add("Kinematics", "H", "A particle moves along a straight line such that its displacement x at time t is given by x² = t² + 1. The acceleration of the particle is proportional to:", ["1/x", "1/x²", "1/x³", "x²"], 2, "2x v = 2t => x v = t => v = t/x. a = dv/dt = (x - t v)/x^2 = (x - t^2/x)/x^2 = (x^2 - t^2)/x^3 = 1/x^3.")
add("Kinematics", "M", "A stone is dropped from a height H. It hits the ground with speed V. If it is dropped from height 4H, its speed on hitting the ground will be:", ["V", "2V", "3V", "4V"], 1, "V = √(2gH). For 4H: V' = √(2g(4H)) = 2 √(2gH) = 2V.")
add("Kinematics", "H", "A swimmer can swim at 4 km/h in still water. He crosses a 1 km wide river flowing at 3 km/h in shortest time. The time taken and drift are:", ["15 min, 0.75 km", "15 min, 1 km", "20 min, 0.75 km", "20 min, 1 km"], 0, "Shortest time path: swim straight across. t = 1/4 h = 15 min. Drift = v_river * t = 3 * 0.25 = 0.75 km.")

# Projectile (P021-P030)
add("Projectile & Circular Motion", "M", "A particle is projected at an angle of 60° with horizontal with velocity 20 m/s. Time of flight T and max range R are: (g = 10 m/s²)", ["3√3 s and 20√3 m", "2√3 s and 20√3 m", "2√3 s and 40 m", "3√3 s and 40 m"], 1, "T = 2u sinθ/g = 2(20)(√3/2)/10 = 2√3 s. R = u² sin(2θ)/g = 400 sin(120°)/10 = 20√3 m.")
add("Projectile & Circular Motion", "H", "Two projectiles thrown with same speed at complementary angles θ and 90°-θ have maximum heights H1 and H2. Their horizontal range R is given by:", ["R = √(H1 H2)", "R = 2 √(H1 H2)", "R = 4 √(H1 H2)", "R = 4 (H1 + H2)"], 2, "H1 = u² sin²θ / 2g, H2 = u² cos²θ / 2g => H1 H2 = u^4 sin²θ cos²θ / 4g² = (u² sin 2θ / 4g)² = R² / 16 => R = 4 √(H1 H2).")
add("Projectile & Circular Motion", "M", "A car of mass 1000 kg moves on a circular road of radius 100 m at 10 m/s. The tan θ for banking without friction is: (g = 10 m/s²)", ["0.01", "0.1", "1", "0.5"], 1, "tan θ = v² / (r g) = 10^2 / (100 * 10) = 100 / 1000 = 0.1.")
add("Projectile & Circular Motion", "H", "A body moves in a horizontal circle of radius 0.5 m with constant angular speed 4 rad/s. Its linear speed and centripetal acceleration are:", ["2 m/s, 8 m/s²", "1 m/s, 4 m/s²", "2 m/s, 4 m/s²", "1 m/s, 8 m/s²"], 0, "v = r ω = 0.5 * 4 = 2 m/s. a_c = v² / r = 4 / 0.5 = 8 m/s².")
add("Projectile & Circular Motion", "H", "A projectile is fired at 45° to horizontal. At the highest point of its trajectory, the ratio of its kinetic energy to initial kinetic energy is:", ["0", "0.25", "0.5", "0.707"], 2, "At top, v_x = u cos 45° = u / √2. KE_top = 0.5 m (u/√2)^2 = 0.25 m u^2 = 0.5 KE_initial. Ratio = 0.5.")
add("Projectile & Circular Motion", "M", "Angle of projection for which horizontal range is equal to four times the maximum height is:", ["30°", "45°", "60°", "75°"], 1, "R = 4H => (u² sin 2θ)/g = 4 (u² sin²θ / 2g) => 2 sin θ cos θ = 2 sin² θ => tan θ = 1 => θ = 45°.")
add("Projectile & Circular Motion", "H", "A particle of mass m executes uniform circular motion of radius r with constant speed v. In half a revolution, the magnitude of change in momentum is:", ["0", "m v", "2 m v", "m v √2"], 2, "Initial v1 = v i, final v2 = -v i. Change Δp = m v2 - m v1 = -2 m v i => Magnitude = 2 m v.")
add("Projectile & Circular Motion", "H", "Maximum speed with which a car can take a turn on a flat road of radius 20 m with coefficient of friction μ = 0.5 is: (g = 10 m/s²)", ["5 m/s", "10 m/s", "14.14 m/s", "20 m/s"], 1, "v_max = √(μ r g) = √(0.5 * 20 * 10) = √100 = 10 m/s.")
add("Projectile & Circular Motion", "M", "Work done by centripetal force on a body moving in a circular path during one complete revolution is:", ["2 π r F_c", "π r F_c", "F_c / (2 π r)", "Zero"], 3, "Centripetal force is always perpendicular to instantaneous velocity (θ = 90°), so work W = 0.")
add("Projectile & Circular Motion", "H", "A stone tied to a string of length L is whirled in a vertical circle. The minimum speed required at the bottom to complete the vertical loop is:", ["√(g L)", "√(3 g L)", "√(5 g L)", "√(7 g L)"], 2, "Critical velocity at top = √(g L). By energy conservation, minimum speed at bottom v_bottom = √(5 g L).")

# Newton's Laws (P031-P040)
add("Newton’s Laws of Motion", "M", "A block of mass 5 kg is placed on a rough incline of angle 30°. If μ = 1/√3, the acceleration of the block down the incline is: (g = 10 m/s²)", ["0 m/s²", "2.5 m/s²", "5 m/s²", "10 m/s²"], 0, "Net force = mg sin 30° - μ mg cos 30° = mg(0.5 - (1/√3)(√3/2)) = mg(0.5 - 0.5) = 0. Block remains stationary.")
add("Newton’s Laws of Motion", "H", "Two blocks of masses 3 kg and 5 kg are connected by a string over a frictionless pulley (Atwood machine). The acceleration of the system is: (g = 10 m/s²)", ["1.25 m/s²", "2.5 m/s²", "5 m/s²", "3 m/s²"], 1, "a = (m2 - m1)g / (m1 + m2) = (5 - 3)*10 / (5 + 3) = 20 / 8 = 2.5 m/s².")
add("Newton’s Laws of Motion", "M", "A 1000 kg rocket expels gas at a rate of 5 kg/s with an exhaust velocity of 400 m/s. The initial thrust on the rocket is:", ["1000 N", "2000 N", "4000 N", "5000 N"], 1, "Thrust F = v_rel (dm/dt) = 400 * 5 = 2000 N.")
add("Newton’s Laws of Motion", "H", "A 60 kg man stands inside an elevator accelerating upwards at 2 m/s². The apparent weight of the man recorded by a scale is: (g = 10 m/s²)", ["480 N", "600 N", "720 N", "840 N"], 2, "N = m(g + a) = 60(10 + 2) = 60 * 12 = 720 N.")
add("Newton’s Laws of Motion", "H", "A force F = 50 N acts on a 10 kg block resting on a horizontal rough surface (μ_s = 0.4, μ_k = 0.3). The frictional force acting on the block is: (g = 10 m/s²)", ["30 N", "40 N", "50 N", "0 N"], 0, "Max static friction f_s_max = μ_s N = 0.4 * 10 * 10 = 40 N. Since F (50N) > f_s_max (40N), the block slides. Kinetic friction f_k = μ_k N = 0.3 * 100 = 30 N.")
add("Newton’s Laws of Motion", "M", "Impulse delivered by a force of 10 N acting on a body for 0.2 seconds is:", ["2 N·s", "5 N·s", "20 N·s", "50 N·s"], 0, "Impulse J = F * Δt = 10 * 0.2 = 2 N·s.")
add("Newton’s Laws of Motion", "H", "A bullet of mass 10 g moving at 400 m/s penetrates a wooden block and stops in 0.02 seconds. The average retarding force on the bullet is:", ["100 N", "200 N", "400 N", "800 N"], 1, "a = (v - u)/t = (0 - 400)/0.02 = -20000 m/s². Force F = m a = 0.01 * 20000 = 200 N.")
add("Newton’s Laws of Motion", "H", "Three blocks of masses 1 kg, 2 kg, and 3 kg are placed in contact on a smooth horizontal table. A horizontal force of 12 N is applied to 1 kg block. The contact force between 2 kg and 3 kg blocks is:", ["2 N", "4 N", "6 N", "8 N"], 2, "Total acceleration a = 12 / (1 + 2 + 3) = 2 m/s². Contact force on 3 kg block = m3 * a = 3 * 2 = 6 N.")
add("Newton’s Laws of Motion", "M", "Which of Newton's laws of motion provides the quantitative definition of force?", ["First Law", "Second Law", "Third Law", "Law of Gravitation"], 1, "Newton's Second Law F = dp/dt = ma gives the quantitative measurement of force.")
add("Newton’s Laws of Motion", "H", "A monkey of mass 20 kg climbs up a light rope attached to a ceiling with an acceleration of 2 m/s². Tension in the rope is: (g = 10 m/s²)", ["160 N", "200 N", "240 N", "280 N"], 2, "T - mg = ma => T = m(g + a) = 20(10 + 2) = 240 N.")

# Work (P041-P050)
add("Work, Energy, & Power", "H", "A 2 kg ball is dropped from a height of 5 m and bounces back to a height of 3.2 m. The percentage of initial mechanical energy lost during collision is:", ["36%", "40%", "56%", "64%"], 0, "E1 = mgh1 = 2(10)(5) = 100 J. E2 = mgh2 = 2(10)(3.2) = 64 J. Energy lost = (100 - 64)/100 = 36%.")
add("Work, Energy, & Power", "H", "A body of mass 1 kg initially at rest explodes into 3 equal parts. Two fragments fly off at 90° to each other with speed 30 m/s each. The speed of the third fragment is:", ["10√2 m/s", "20√2 m/s", "30√2 m/s", "15√2 m/s"], 2, "Each mass m = 1/3 kg. p1 = (1/3)*30 = 10 N·s i, p2 = (1/3)*30 = 10 N·s j. p3 = -(10i + 10j) => |p3| = 10√2 N·s. Speed v3 = |p3| / (1/3) = 30√2 m/s.")
add("Work, Energy, & Power", "M", "Work done by a variable force F = (3 x² + 2 x) N in displacing a particle from x = 0 to x = 2 m is:", ["8 J", "12 J", "16 J", "20 J"], 1, "W = ∫ (3x² + 2x) dx from 0 to 2 = [x³ + x²]_0^2 = (8 + 4) - 0 = 12 J.")
add("Work, Energy, & Power", "H", "An engine pumps 100 kg of water per minute to a height of 10 m. The power of the engine in Watts is: (g = 10 m/s²)", ["100 W", "166.7 W", "1000 W", "6000 W"], 1, "Work W = mgh = 100 * 10 * 10 = 10000 J per 60 s. Power P = 10000 / 60 = 166.7 W.")
add("Work, Energy, & Power", "H", "A mass of 0.5 kg attached to a spring of force constant k = 200 N/m is compressed by 0.1 m. The maximum speed achieved when released is:", ["1 m/s", "2 m/s", "4 m/s", "5 m/s"], 1, "0.5 k x^2 = 0.5 m v^2 => 200 * (0.1)^2 = 0.5 * v^2 => 2 = 0.5 v^2 => v^2 = 4 => v = 2 m/s.")
add("Work, Energy, & Power", "M", "If linear momentum of a body is increased by 50%, its kinetic energy increases by:", ["50%", "100%", "125%", "150%"], 2, "KE = p² / 2m. If p' = 1.5 p, KE' = (1.5)² KE = 2.25 KE. Fractional increase = 1.25 = 125%.")
add("Work, Energy, & Power", "H", "A 1000 kg car moving at 72 km/h is brought to rest over a distance of 40 m. The average braking force applied is:", ["3000 N", "4000 N", "5000 N", "6000 N"], 2, "u = 72 * 5/18 = 20 m/s. Work done by brakes W = 0.5 m u^2 = 0.5 * 1000 * 400 = 200000 J. Force F = W / s = 200000 / 40 = 5000 N.")
add("Work, Energy, & Power", "M", "1 Horsepower (1 h.p.) is equal to how many Watts?", ["746 W", "1000 W", "500 W", "750 W"], 0, "1 h.p. = 746 Watts by standard definition.")
add("Work, Energy, & Power", "H", "A ball of mass m moving with velocity v collides head-on elastically with an identical ball at rest. The velocities of the two balls after collision are:", ["0 and v", "v and 0", "v/2 and v/2", "-v and v"], 0, "In elastic 1D collision of equal masses, velocities exchange completely: ball 1 comes to rest (0), ball 2 moves with v.")
add("Work, Energy, & Power", "H", "Potential energy function of a conservative system is U(x) = x² - 4x. The equilibrium position and nature of equilibrium are:", ["x = 2 m, Stable", "x = 2 m, Unstable", "x = 4 m, Stable", "x = 0 m, Neutral"], 0, "F = -dU/dx = -(2x - 4) = 0 => x = 2 m. d²U/dx² = 2 > 0 => Stable equilibrium.")

# Rotational (P051-P060)
add("Rotational Motion", "H", "A solid sphere (mass M, radius R) and a hollow sphere (mass M, radius R) roll without slipping down an incline. The ratio of their accelerations (solid : hollow) is:", ["14:10", "10:7", "25:21", "7:5"], 2, "a = g sinθ / (1 + k²/R²). Solid sphere k²/R² = 2/5, Hollow sphere k²/R² = 2/3. Ratio = (1 + 2/3) / (1 + 2/5) = (5/3) / (7/5) = 25/21.")
add("Rotational Motion", "M", "Moment of inertia of a uniform thin rod of mass M and length L about an axis perpendicular to its length through its center of mass is:", ["M L² / 3", "M L² / 6", "M L² / 12", "M L² / 2"], 2, "Standard moment of inertia for thin rod center = (1/12) M L².")
add("Rotational Motion", "H", "A wheel of moment of inertia 2 kg·m² rotating at 30 rad/s is brought to rest by a constant torque in 10 seconds. The torque applied is:", ["3 N·m", "6 N·m", "10 N·m", "12 N·m"], 1, "α = Δω / Δt = (0 - 30)/10 = -3 rad/s². Torque τ = I α = 2 * 3 = 6 N·m.")
add("Rotational Motion", "M", "A solid disc of mass 2 kg and radius 0.2 m rotates about its central axis at 10 rad/s. Its rotational kinetic energy is:", ["1 J", "2 J", "4 J", "8 J"], 1, "I = 0.5 M R² = 0.5 * 2 * (0.04) = 0.04 kg·m². KE = 0.5 I ω² = 0.5 * 0.04 * 100 = 2 J.")
add("Rotational Motion", "H", "A ballet dancer spins with angular velocity ω_0 with her arms outstretched. When she pulls her arms in, her moment of inertia decreases to I_0 / 2. Her new angular velocity and kinetic energy are:", ["2 ω_0, 2 KE_0", "2 ω_0, KE_0", "ω_0 / 2, KE_0 / 2", "4 ω_0, 4 KE_0"], 0, "By conservation of angular momentum: I_0 ω_0 = (I_0/2) ω' => ω' = 2 ω_0. KE' = 0.5 (I_0/2) (2ω_0)² = I_0 ω_0² = 2 KE_0.")
add("Rotational Motion", "H", "Ratio of moment of inertia of a circular ring to a circular disc of same mass M and radius R about their central symmetry axis is:", ["1 : 2", "2 : 1", "1 : 1", "4 : 1"], 1, "I_ring = M R², I_disc = 0.5 M R². Ratio = 1 / 0.5 = 2 : 1.")
add("Rotational Motion", "M", "The radius of gyration of a solid sphere of radius R about a tangent axis is:", ["√(2/5) R", "√(7/5) R", "√(3/5) R", "√(1/5) R"], 1, "By parallel axis theorem: I_tangent = I_cm + M R² = 2/5 M R² + M R² = 7/5 M R² = M k² => k = √(7/5) R.")
add("Rotational Motion", "H", "A ring of mass 1 kg and radius 0.5 m rolls without slipping on a horizontal surface at 4 m/s. Its total kinetic energy is:", ["8 J", "12 J", "16 J", "20 J"], 2, "KE_total = 0.5 M v² (1 + k²/R²). For ring k²/R² = 1. KE = 0.5 (1)(4²)(1 + 1) = 0.5 * 16 * 2 = 16 J.")
add("Rotational Motion", "H", "Vector relation between linear velocity v, angular velocity ω, and position vector r is:", ["v = ω x r", "v = r x ω", "ω = v x r", "r = v x ω"], 0, "Linear velocity is vector cross product of angular velocity and position vector: v = ω x r.")
add("Rotational Motion", "M", "Angular momentum of a system of particles is conserved whenever:", ["Net external force is zero", "Net external torque is zero", "Net work done is zero", "Internal forces are zero"], 1, "By τ_net = dL/dt, angular momentum L is conserved when net external torque τ_net = 0.")

# Gravitation (P061-P070)
add("Gravitation", "M", "Escape velocity from the surface of Earth is 11.2 km/s. If a planet has same density but twice the radius of Earth, its escape velocity will be:", ["5.6 km/s", "11.2 km/s", "22.4 km/s", "44.8 km/s"], 2, "v_e = √(2GM/R) ∝ R (for constant density ρ). Since R' = 2R, v_e' = 2 v_e = 2(11.2) = 22.4 km/s.")
add("Gravitation", "H", "A satellite orbits Earth at height equal to Earth's radius R. The orbital velocity of the satellite is: (g = 9.8 m/s², R = 6400 km)", ["7.9 km/s", "5.59 km/s", "11.2 km/s", "3.95 km/s"], 1, "v_o = √(g R² / (R + h)) = √(g R / 2) = √(9.8 * 6400 * 10^3 / 2) = √31.36 x 10^6 ≈ 5590 m/s = 5.59 km/s.")
add("Gravitation", "M", "Acceleration due to gravity at a depth d below the Earth's surface becomes g / 4. The depth d in terms of Earth radius R is:", ["R / 4", "R / 2", "3R / 4", "R"], 2, "g_d = g(1 - d/R) = g/4 => 1 - d/R = 1/4 => d/R = 3/4 => d = 3R/4.")
add("Gravitation", "H", "Two point masses m and 4m are separated by a distance r. The gravitational potential is zero at a point between them where electric/gravitational field is zero. That point is at a distance from mass m of:", ["r / 2", "r / 3", "r / 4", "r / 5"], 1, "Field balance: G m / x² = G (4m) / (r - x)² => 1/x = 2/(r - x) => r - x = 2x => 3x = r => x = r/3.")
add("Gravitation", "H", "If the radius of Earth's orbit around the Sun were shrunk to one-fourth of its present value, the length of the year would become:", ["1/2 year", "1/4 year", "1/8 year", "1/16 year"], 2, "Kepler's 3rd Law: T² ∝ r³ => T' / T = (r'/r)^(3/2) = (1/4)^(3/2) = 1/8. Year length becomes 1/8 year.")
add("Gravitation", "M", "Weight of a body of mass m at the center of Earth is:", ["m g", "m g / 2", "Infinite", "Zero"], 3, "At Earth's center d = R, so g_center = g(1 - R/R) = 0. Weight W = m(0) = 0.")
add("Gravitation", "H", "The potential energy of a satellite of mass m orbiting Earth (mass M, radius R) in a circular orbit of radius 2R is:", ["- G M m / R", "- G M m / (2 R)", "- G M m / (4 R)", "+ G M m / (2 R)"], 1, "Gravitational potential energy U = - G M m / r = - G M m / (2 R).")
add("Gravitation", "H", "Ratio of binding energy of a satellite orbiting at surface of Earth to its kinetic energy is:", ["1 : 1", "2 : 1", "1 : 2", "1 : 4"], 0, "Kinetic energy KE = G M m / (2R). Binding Energy BE = - Total Energy = G M m / (2R). Ratio BE : KE = 1 : 1.")
add("Gravitation", "M", "Geostationary satellite orbits Earth with a period of:", ["6 hours", "12 hours", "24 hours", "48 hours"], 2, "A geostationary satellite matches Earth's diurnal rotation period of 24 hours.")
