add("Thermal Properties", "M", "The temperature at which Celsius and Fahrenheit scales record the same numerical value is:", ["0°", "-20°", "-40°", "-80°"], 2, "C / 5 = (F - 32) / 9. Setting C = F = x: x / 5 = (x - 32) / 9 => 9x = 5x - 160 => 4x = -160 => x = -40°.")
add("Thermal Properties", "H", "Newton's law of cooling is valid for small temperature differences up to about:", ["5°C", "30°C", "50°C", "100°C"], 1, "Newton's law of cooling is an approximation of Stefan's law valid for small temperature excess ΔT ≤ 30°C.")
add("Thermal Properties", "H", "Coefficient of volume expansion of a metal is γ = 3.6 x 10^-5 /°C. Its coefficient of linear expansion α is:", ["1.2 x 10^-5 /°C", "1.8 x 10^-5 /°C", "7.2 x 10^-5 /°C", "10.8 x 10^-5 /°C"], 0, "γ = 3 α => α = γ / 3 = 3.6 x 10^-5 / 3 = 1.2 x 10^-5 /°C.")
add("Thermal Properties", "M", "Density of water is maximum at temperature:", ["0°C", "4°C", "100°C", "-4°C"], 1, "Anomalous expansion of water results in maximum density at 4°C (1000 kg/m³).")
