add("Kinetic Theory of Gases", "H", "At what temperature does the RMS velocity of Hydrogen gas (M=2) equal the RMS velocity of Oxygen gas (M=32) at 47°C?", ["20 K", "40 K", "80 K", "160 K"], 0, "T_H2 / M_H2 = T_O2 / M_O2 => T_H2 / 2 = 320 / 32 = 10 => T_H2 = 20 K.")
add("Kinetic Theory of Gases", "M", "Boyle's law holds good for ideal gases undergoing:", ["Isothermal process", "Adiabatic process", "Isobaric process", "Isochoric process"], 0, "Boyle's law P V = constant requires constant temperature (Isothermal).")
