add("Electrostatics", "M", "SI unit of permittivity of free space (ε0) is:", ["C² N^-1 m^-2", "N m² C^-2", "C N^-1 m^-1", "C² N m²"], 0, "F = q1 q2 / (4 π ε0 r²) => ε0 = q1 q2 / (4 π F r²) = C² N^-1 m^-2.")
add("Electrostatics", "H", "Work done in rotating an electric dipole of moment p through 180° from stable equilibrium position in uniform electric field E is:", ["p E", "2 p E", "0", "-p E"], 1, "W = p E (cos θ1 - cos θ2) = p E (cos 0° - cos 180°) = p E (1 - (-1)) = 2 p E.")
add("Electrostatics", "H", "Electric field intensity just outside a charged conductor of surface charge density σ in vacuum is:", ["σ / ε0", "σ / (2 ε0)", "2 σ / ε0", "Zero"], 0, "By Gauss's law just outside a conductor surface: E = σ / ε0.")
