add("Ray Optics & Optical Instruments", "M", "Focal length of a convex lens is 20 cm. Its optical power in Diopters is:", ["+2 D", "+5 D", "-5 D", "+0.05 D"], 1, "P = 1 / f(in meters) = 1 / 0.2 m = +5 D.")
add("Ray Optics & Optical Instruments", "H", "A convex lens of focal length 20 cm forms a real image 3 times the size of an object. Distance of object from lens is:", ["26.67 cm", "13.33 cm", "40 cm", "60 cm"], 0, "Real image => m = -3 = v / u => v = -3 u. Lens formula: 1/f = 1/v - 1/u => 1/20 = 1/(-3u) - 1/u = -4/(3u) => 3u = -80 => u = -26.67 cm.")
add("Ray Optics & Optical Instruments", "M", "Critical angle for total internal reflection from a glass medium (n = 1.5) to air is approximately:", ["30°", "41.8°", "48.6°", "60°"], 1, "sin C = 1 / n = 1 / 1.5 = 0.6667 => C = sin^-1(0.6667) ≈ 41.8°.")
add("Ray Optics & Optical Instruments", "H", "An equiconvex lens made of glass (n = 1.5) has focal length 20 cm in air. Radius of curvature R of each surface is:", ["10 cm", "20 cm", "30 cm", "40 cm"], 1, "Lens maker's formula: 1/f = (n - 1)(1/R1 - 1/R2) => 1/20 = (1.5 - 1)(1/R - (-1/R)) = 0.5 (2/R) = 1/R => R = 20 cm.")
add("Ray Optics & Optical Instruments", "H", "Minimum deviation produced by a 60° glass prism (n = √2) is:", ["15°", "30°", "45°", "60°"], 1, "n = sin((A + δ_m)/2) / sin(A/2) => √2 = sin((60° + δ_m)/2) / sin 30° => sin((60° + δ_m)/2) = √2 * 0.5 = 1/√2 => (60° + δ_m)/2 = 45° => 60° + δ_m = 90° => δ_m = 30°.")
add("Ray Optics & Optical Instruments", "M", "A person suffering from myopia (nearsightedness) can be corrected using:", ["Convex lens", "Concave lens", "Cylindrical lens", "Bifocal lens"], 1, "Myopia causes light rays to focus in front of retina; a diverging concave lens moves focus back to retina.")
add("Ray Optics & Optical Instruments", "H", "An astronomical telescope has objective focal length 100 cm and eyepiece focal length 5 cm. Magnifying power in normal adjustment and tube length are:", ["20, 105 cm", "20, 95 cm", "50, 105 cm", "5, 500 cm"], 0, "Magnification M = f_o / f_e = 100 / 5 = 20. Tube length L = f_o + f_e = 100 + 5 = 105 cm.")
add("Ray Optics & Optical Instruments", "H", "An object is placed 15 cm in front of a concave mirror of focal length 10 cm. Image distance and nature are:", ["-30 cm, Real & inverted", "+30 cm, Virtual & erect", "-60 cm, Real & inverted", "-15 cm, Real & inverted"], 0, "1/f = 1/v + 1/u => -1/10 = 1/v - 1/15 => 1/v = 1/15 - 1/10 = (2-3)/30 = -1/30 => v = -30 cm. Image is real and inverted.")
add("Ray Optics & Optical Instruments", "M", "Velocity of light in a medium of refractive index n = 1.5 is:", ["3 x 10^8 m/s", "2 x 10^8 m/s", "1.5 x 10^8 m/s", "4.5 x 10^8 m/s"], 1, "v = c / n = (3 x 10^8) / 1.5 = 2 x 10^8 m/s.")
add("Ray Optics & Optical Instruments", "H", "Two thin lenses of powers +5 D and -3 D are placed in contact. Equivalent focal length of the combination is:", ["20 cm", "50 cm", "100 cm", "25 cm"], 1, "P_eq = P1 + P2 = 5 - 3 = +2 D. Focal length f = 1 / P_eq = 1 / 2 m = 50 cm.")

# Wave Optics (P211-P220)
add("Wave Optics", "M", "In Young's double slit experiment, fringe width β = 0.6 mm. If wavelength of light is doubled and slit separation halved, new fringe width becomes:", ["0.6 mm", "1.2 mm", "2.4 mm", "4.8 mm"], 2, "β = λ D / d. If λ' = 2 λ and d' = d/2: β' = (2 λ) D / (d/2) = 4 β = 4 * 0.6 = 2.4 mm.")
add("Wave Optics", "H", "Two coherent monochromatic light waves of intensities I and 4I interfere. Maximum and minimum intensities in interference pattern are:", ["5I and 3I", "9I and I", "9I and 3I", "4I and I"], 1, "I_max = (√I + √4I)² = (1 + 2)² I = 9I. I_min = (√4I - √I)² = (2 - 1)² I = I.")
add("Wave Optics", "M", "Brewster's angle for glass of refractive index n = √3 is:", ["30°", "45°", "60°", "75°"], 2, "tan i_p = n = √3 => i_p = 60°.")
add("Wave Optics", "H", "Unpolarized light of intensity I0 is incident on a polarizer. Intensity of transmitted polarized light is:", ["I0", "I0 / 2", "I0 / 4", "Zero"], 1, "Unpolarized light passing through any single ideal linear polarizer reduces to half intensity I0 / 2.")
add("Wave Optics", "H", "Angular width of central maximum in single slit diffraction pattern of slit width a = 0.1 mm with light wavelength λ = 600 nm is:", ["0.012 rad", "0.006 rad", "0.024 rad", "0.003 rad"], 0, "Angular width 2 θ = 2 λ / a = 2 * (600 x 10^-9) / (10^-4) = 1200 x 10^-5 = 0.012 rad.")
